const produceTranslations = {
  Apple: { name: "ఆపిల్", benefits: ["పీచు జీర్ణక్రియ సరిగా ఉండటానికి, కడుపు నిండిన భావనకు తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి, శరీరంలో కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "పాలీఫెనాల్స్ వంటి మొక్కల పదార్థాలు ఆహారంలో వైవిధ్యాన్ని పెంచుతాయి."], season: "వేసవి చివరి నుంచి శరదృతువు వరకు; ఏడాది పొడవునా లభిస్తుంది.", tips: ["కడిగి, ఎక్కువ పీచు కోసం తొక్కతో తినండి.", "ముక్కలను ఓట్స్, సలాడ్ లేదా నట్ బటర్‌తో తినండి."], careful: "ఆపిల్ లేదా పుప్పొడి అలర్జీ ఉన్నవారికి పచ్చి ఆపిల్ తింటే నోటిలో అలర్జీ లక్షణాలు రావచ్చు. తినే ముందు కడగండి." },
  Apricot: { name: "ఆప్రికాట్", benefits: ["నారింజ రంగు ఆప్రికాట్‌లోని బీటా కెరోటిన్ విటమిన్ ఏగా మారి చూపుకు తోడ్పడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి సహాయపడుతుంది.", "విటమిన్ సి కొల్లాజెన్ తయారీకి, మొక్కల ఆహారం నుంచి ఇనుము శోషణకు తోడ్పడుతుంది."], season: "వసంతం చివరి నుంచి వేసవి వరకు.", tips: ["తాజా ఆప్రికాట్‌ను చిరుతిండిగా లేదా పెరుగుతో తినండి.", "ఎండిన ఆప్రికాట్‌లో సహజ చక్కెరలు ఎక్కువగా ఉంటాయి; లేబుల్ చూడండి."], careful: "ఎండిన ఆప్రికాట్‌లో కొందరికి ఇబ్బంది కలిగించే సల్ఫైట్లు ఉండవచ్చు. సున్నితత్వం ఉంటే లేబుల్ చూడండి." },
  Avocado: { name: "అవకాడో", benefits: ["సంతృప్త కొవ్వుకు బదులుగా అసంతృప్త కొవ్వు తీసుకుంటే గుండె ఆరోగ్యానికి తోడ్పడవచ్చు.", "పీచు జీర్ణక్రియకు, కడుపు నిండిన భావనకు సహాయపడుతుంది.", "ఫోలేట్ కణాల సాధారణ పెరుగుదల, పనితీరుకు అవసరం."], season: "ఏడాది పొడవునా లభిస్తుంది; రకాన్ని బట్టి పంట కాలం మారుతుంది.", tips: ["మెత్తగా చేసి బ్రెడ్‌పై రాయండి.", "సలాడ్‌లో కలపండి లేదా క్రీమీ డ్రెస్సింగ్‌గా చేయండి."], careful: "అవకాడోలో విటమిన్ కె ఉంటుంది. వార్ఫరిన్ వాడేవారు విటమిన్ కె తీసుకునే పరిమాణాన్ని స్థిరంగా ఉంచి, ఆహారంలో పెద్ద మార్పుల ముందు వైద్య బృందాన్ని సంప్రదించాలి." },
  Banana: { name: "అరటిపండు", benefits: ["పొటాషియం కండరాల సాధారణ పనితీరుకు, శరీర ద్రవాల సమతుల్యతకు తోడ్పడుతుంది.", "విటమిన్ బి6 ఆహారాన్ని శక్తిగా మార్చడానికి, కొన్ని మెదడు రసాయనాల తయారీకి సహాయపడుతుంది.", "పీచు ఆరోగ్యకరమైన జీర్ణక్రియకు తోడ్పడుతుంది."], season: "ఏడాది పొడవునా లభిస్తుంది.", tips: ["చిరుతిండిగా తినండి లేదా తృణధాన్యాల్లో కలపండి.", "బాగా పండిన ముక్కలను గడ్డకట్టి స్మూతీలో వాడండి."], careful: "తీవ్రమైన మూత్రపిండ వ్యాధి ఉన్నవారు పొటాషియం పరిమాణాన్ని గమనించాల్సి రావచ్చు. వైద్యుల వ్యక్తిగత సూచనలు పాటించండి." },
  Blueberry: { name: "బ్లూబెర్రీ", benefits: ["పీచు జీర్ణక్రియ సరిగా ఉండటానికి తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి తోడ్పడుతుంది.", "బ్లూబెర్రీలోని ఆంథోసయానిన్లు రంగుల మొక్కల పదార్థాలు; ఇవి వైవిధ్యమైన ఆహారంలో భాగం."], season: "వసంతం చివరి నుంచి వేసవి వరకు; గడ్డకట్టిన బెర్రీలు ఏడాది పొడవునా లభిస్తాయి.", tips: ["తాజా లేదా గడ్డకట్టిన బెర్రీలను ఓట్స్, పెరుగు లేదా పాన్‌కేక్ మిశ్రమంలో కలపండి.", "తాజా బెర్రీలను తినే ముందు కడగండి."], careful: "వార్ఫరిన్ వాడేవారు తమ చికిత్సపై ప్రభావం చూపే ఆహారాలను స్థిరంగా తీసుకోవడం గురించి వైద్యులను అడగాలి." },
  Grapefruit: { name: "గ్రేప్‌ఫ్రూట్", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, మొక్కల ఆహారం నుంచి ఇనుము శోషణకు తోడ్పడుతుంది.", "నీరు, పీచు కలిసిన చిరుతిండి కడుపు నిండిన భావన ఇస్తుంది.", "ఫోలేట్ కణాల సాధారణ పెరుగుదల, పనితీరుకు తోడ్పడుతుంది."], season: "శీతాకాలం నుంచి వసంతం ప్రారంభం వరకు.", tips: ["ఉదయం పూట ముక్కలుగా తినండి.", "అవకాడో, ఆకుకూరలతో సలాడ్‌లో కలపండి."], careful: "గ్రేప్‌ఫ్రూట్ లేదా దాని రసం కొన్ని మందులతో ప్రతిచర్య కలిగించవచ్చు. మందులు వాడుతుంటే తినే ముందు వైద్యుడు లేదా ఫార్మసిస్ట్‌ను అడగండి." },
  Kiwi: { name: "కివి", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి సహాయపడుతుంది.", "పొటాషియం శరీర ద్రవాల సమతుల్యతను కాపాడుతుంది."], season: "రకాన్ని బట్టి శరదృతువు చివరి నుంచి వసంతం వరకు.", tips: ["చెంచాతో తినండి లేదా తొక్క తీసి పండ్ల సలాడ్‌లో కలపండి.", "ఓట్స్ లేదా పెరుగుతో తినండి."], careful: "కివి వల్ల కొందరికి అలర్జీ రావచ్చు; లేటెక్స్ లేదా పుప్పొడి అలర్జీ ఉన్నవారిలోనూ ఇది జరగవచ్చు." },
  Orange: { name: "నారింజ", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "మొక్కల ఆహారం నుంచి ఇనుము శోషణకు విటమిన్ సి సహాయపడుతుంది.", "మొత్తం పండులోని పీచు జీర్ణక్రియకు తోడ్పడుతుంది."], season: "చాలా రకాల నారింజలకు శీతాకాలం నుంచి వసంతం వరకు.", tips: ["పీచు కోసం రసం కంటే మొత్తం పండును ఎంచుకోండి.", "ముక్కలను సలాడ్ లేదా భోజన పెట్టెలో చేర్చండి."], careful: "కొంతమందికి సిట్రస్ పండ్లు గుండెల్లో మంటను పెంచవచ్చు. మందులతో సిట్రస్ ప్రతిచర్య ఉందా అని ఫార్మసిస్ట్‌ను అడగండి." },
  Pear: { name: "బేరిపండు", benefits: ["పీచు మల విసర్జన క్రమంగా ఉండటానికి, కడుపు నిండిన భావనకు తోడ్పడుతుంది.", "రాగి ఎర్ర రక్త కణాల తయారీకి, శరీర కణజాలాల నిర్వహణకు సహాయపడుతుంది.", "బేరిపండు భోజనాలు, చిరుతిండిలో పండ్ల వైవిధ్యాన్ని పెంచుతుంది."], season: "రకాన్ని బట్టి వేసవి చివరి నుంచి శీతాకాలం వరకు.", tips: ["కడిగిన తర్వాత తొక్కతో తినండి.", "సలాడ్‌లో ముక్కలు వేసుకోండి లేదా ఓట్స్‌తో తినండి."], careful: "పీచు ఎక్కువగా తినే అలవాటు లేకపోతే కొద్దికొద్దిగా పెంచండి; ఒక్కసారిగా పెంచితే కడుపు ఉబ్బరం రావచ్చు." },
  Strawberry: { name: "స్ట్రాబెర్రీ", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "పీచు జీర్ణక్రియకు సహాయపడుతుంది.", "మాంగనీస్ పోషకాల వినియోగానికి, ఎముకల సాధారణ నిర్వహణకు తోడ్పడుతుంది."], season: "వసంతం నుంచి వేసవి ప్రారంభం వరకు; స్థానిక పంట కాలం మారవచ్చు.", tips: ["తాజా బెర్రీలను తృణధాన్యాలు లేదా పెరుగుపై వేయండి.", "ముక్కలు చేసి ఆకుకూరల సలాడ్‌లో కలపండి."], careful: "స్ట్రాబెర్రీ వల్ల కొందరికి అలర్జీ రావచ్చు. తినే ముందు ప్రవహించే నీటిలో కడగండి." },
  Watermelon: { name: "పుచ్చకాయ", benefits: ["పుచ్చకాయలోని నీరు రోజువారీ ద్రవ అవసరాలకు తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి సహాయపడుతుంది.", "లైకోపీన్ ఎరుపు రంగు పండ్లు, కూరగాయల్లో ఉండే సహజ వర్ణద్రవ్యం."], season: "వేసవి.", tips: ["చల్లగా ముక్కలుగా వడ్డించండి.", "పండ్ల సలాడ్‌లో కలపండి లేదా స్మూతీగా చేయండి."], careful: "ఇతర పండ్లలాగే పుచ్చకాయలోనూ కార్బోహైడ్రేట్లు ఉంటాయి. రక్తంలో చక్కెరను గమనించే వారు తమ ఆహార ప్రణాళికకు అనుగుణంగా పరిమాణం చూసుకోవాలి." },
  "Bell Pepper": { name: "క్యాప్సికం", benefits: ["ఎరుపు క్యాప్సికంలో విటమిన్ సి ఉంటుంది; ఇది రోగనిరోధక శక్తికి తోడ్పడుతుంది.", "బీటా కెరోటిన్ విటమిన్ ఏగా మారి చూపుకు సహాయపడుతుంది.", "పీచు ఆరోగ్యకరమైన జీర్ణక్రియకు తోడ్పడుతుంది."], season: "వేసవి నుంచి శరదృతువు ప్రారంభం వరకు; ఏడాది పొడవునా లభిస్తుంది.", tips: ["పచ్చి ముక్కలను హమ్మస్‌తో తినండి.", "ఇతర కూరగాయలతో కాల్చండి లేదా వేయించండి."], careful: "క్యాప్సికం వల్ల కొందరికి గుండెల్లో మంట లేదా జీర్ణ అసౌకర్యం పెరగవచ్చు; వండే విధానం, సహనం వ్యక్తికి వ్యక్తికి మారుతాయి." },
  Broccoli: { name: "బ్రోకలి", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి సహాయపడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి తోడ్పడుతుంది."], season: "శరదృతువు నుంచి వసంతం వరకు; ఏడాది పొడవునా లభిస్తుంది.", tips: ["మెత్తబడే వరకు ఆవిరి మీద ఉడికించండి లేదా ఆలివ్ నూనెతో కాల్చండి.", "పూల ముక్కలను సూప్, ధాన్యాల భోజనం లేదా పాస్తాలో కలపండి."], careful: "బ్రోకలీలో విటమిన్ కె ఉంటుంది. వార్ఫరిన్ వాడేవారు దాని తీసుకునే పరిమాణాన్ని స్థిరంగా ఉంచి, పెద్ద మార్పుల ముందు వైద్య బృందాన్ని సంప్రదించాలి." },
  Carrot: { name: "క్యారెట్", benefits: ["బీటా కెరోటిన్ విటమిన్ ఏగా మారి చూపుకు తోడ్పడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి సహాయపడుతుంది.", "పొటాషియం కండరాల పనితీరుకు, ద్రవాల సమతుల్యతకు తోడ్పడుతుంది."], season: "వేసవి చివరి నుంచి శరదృతువు వరకు; ఏడాది పొడవునా లభిస్తుంది.", tips: ["ముక్కలను పచ్చిగా డిప్‌తో తినండి.", "సూప్, సలాడ్ లేదా సాస్‌లో తురిమి లేదా కాల్చి వాడండి."], careful: "పుప్పొడి-ఆహార అలర్జీ ఉన్నవారికి పచ్చి క్యారెట్ తింటే నోటిలో దురద రావచ్చు; ఉడికించినది బాగా సరిపోవచ్చు." },
  Cauliflower: { name: "కాలీఫ్లవర్", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "ఫోలేట్ కణాల సాధారణ పెరుగుదల, పనితీరుకు సహాయపడుతుంది.", "పీచు జీర్ణక్రియకు తోడ్పడుతుంది."], season: "శరదృతువు నుంచి వసంతం వరకు.", tips: ["పూల ముక్కలను బంగారు రంగు వచ్చే వరకు కాల్చండి.", "సూప్‌లో కలపండి లేదా డిప్‌తో పచ్చిగా తినండి."], careful: "క్రూసిఫెరస్ కూరగాయలు కొందరికి గ్యాస్ లేదా కడుపు ఉబ్బరం కలిగించవచ్చు; పరిమాణాన్ని నెమ్మదిగా పెంచండి." },
  Kale: { name: "కేల్ ఆకుకూర", benefits: ["విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి సహాయపడుతుంది.", "కేల్‌లో ఆకుకూరల్లో కనిపించే ల్యూటీన్ అనే మొక్కల వర్ణద్రవ్యం ఉంటుంది."], season: "చల్లని కాలం; సాధారణంగా శరదృతువు నుంచి వసంతం ప్రారంభం వరకు.", tips: ["సలాడ్ కోసం తరిగిన ఆకులను కొద్దిగా డ్రెస్సింగ్‌తో మర్దన చేయండి.", "సూప్‌లో కలపండి లేదా మెత్తబడే వరకు వేయించండి."], careful: "కేల్‌లో విటమిన్ కె ఉంటుంది. వార్ఫరిన్ వాడేవారు దాని పరిమాణాన్ని స్థిరంగా ఉంచి వైద్య నిపుణుడితో మాట్లాడాలి." },
  Mushroom: { name: "పుట్టగొడుగు", benefits: ["రిబోఫ్లేవిన్, నియాసిన్ ఆహారం నుంచి శక్తి విడుదలకు సహాయపడతాయి.", "సెలీనియం థైరాయిడ్ సాధారణ పనితీరుకు తోడ్పడుతుంది.", "యూవీ కాంతి తగిలిన కొన్ని పుట్టగొడుగుల్లో విటమిన్ డి ఉంటుంది; ప్యాకెట్ చూడండి."], season: "ఏడాది పొడవునా లభిస్తుంది.", tips: ["వెల్లుల్లి, సుగంధ ఆకులతో వేయించండి.", "ముక్కలను ఆమ్లెట్, సూప్ లేదా ధాన్యాల వంటల్లో కలపండి."], careful: "తినడానికి సురక్షితమని గుర్తించిన పుట్టగొడుగులనే తినండి; అడవి పుట్టగొడుగులు విషపూరితం కావచ్చు. తినదగిన పుట్టగొడుగులకూ కొందరికి అలర్జీ ఉంటుంది." },
  Onion: { name: "ఉల్లిపాయ", benefits: ["ఉల్లిపాయ వంటకాలకు రుచి, కొంత పీచు ఇస్తుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి తోడ్పడుతుంది.", "వైవిధ్యమైన ఆహారంలో భాగంగా ఉల్లిపాయ నుంచి క్వెర్సెటిన్ వంటి మొక్కల పదార్థాలు అందుతాయి."], season: "ఏడాది పొడవునా లభిస్తుంది; స్థానిక తాజా పంట కాలం ప్రాంతాన్ని బట్టి మారుతుంది.", tips: ["సలాడ్‌లో పచ్చిగా వాడండి లేదా సూప్, సాస్‌లో ఉడికించండి.", "సహజ తీపి కోసం నెమ్మదిగా వేయించి వాడండి."], careful: "FODMAPలకు సున్నితంగా ఉండేవారికి ఉల్లిపాయ జీర్ణ సమస్యలు కలిగించవచ్చు; సహనం వ్యక్తికి వ్యక్తికి మారుతుంది." },
  Spinach: { name: "పాలకూర", benefits: ["ఫోలేట్ కణాల సాధారణ పెరుగుదలకు అవసరం; గర్భధారణ సమయంలో ఇది ప్రత్యేకంగా ముఖ్యం.", "ఇనుము ఎర్ర రక్త కణాలు ఆక్సిజన్ మోసేందుకు సహాయపడుతుంది; విటమిన్ సి ఉన్న ఆహారంతో మొక్కల ఇనుము బాగా శోషించబడుతుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది."], season: "చల్లని కాలం; సాధారణంగా వసంతం, శరదృతువులో.", tips: ["వంట చివర్లో సూప్ లేదా పాస్తాలో కలపండి.", "విటమిన్ సి కోసం టమాటా, క్యాప్సికం లేదా సిట్రస్‌తో తినండి."], careful: "పాలకూరలో విటమిన్ కె ఉంటుంది; వార్ఫరిన్ వాడేవారు దాని పరిమాణాన్ని స్థిరంగా ఉంచాలి. కొన్ని రకాల మూత్రపిండ రాళ్ల చరిత్ర ఉంటే ఆక్సలేట్ ఉన్న ఆహారం గురించి వ్యక్తిగత వైద్య సూచన తీసుకోండి." },
  "Sweet Potato": { name: "చిలగడదుంప", benefits: ["బీటా కెరోటిన్ విటమిన్ ఏగా మారి చూపుకు తోడ్పడుతుంది.", "పీచు జీర్ణక్రియకు, కడుపు నిండిన భావనకు సహాయపడుతుంది.", "పొటాషియం కండరాల సాధారణ పనితీరుకు తోడ్పడుతుంది."], season: "శరదృతువులో పంట; నిల్వ చేసినవి ఏడాది పొడవునా లభిస్తాయి.", tips: ["మొత్తంగా కాల్చి బీన్స్ లేదా పెరుగుతో వడ్డించండి.", "ముక్కలుగా కోసి కాల్చి సైడ్ డిష్‌గా తినండి."], careful: "తీవ్రమైన మూత్రపిండ వ్యాధి ఉన్నవారు పొటాషియం గమనించాల్సి రావచ్చు. వైద్య బృందం సూచన పాటించండి." },
  Tomato: { name: "టమాటా", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "పొటాషియం కండరాల పనితీరుకు, ద్రవాల సమతుల్యతకు సహాయపడుతుంది.", "టమాటాలో లైకోపీన్ అనే సహజ మొక్కల వర్ణద్రవ్యం ఉంటుంది."], season: "వేసవి నుంచి శరదృతువు ప్రారంభం వరకు; డబ్బా టమాటాలు ఏడాది పొడవునా లభిస్తాయి.", tips: ["సాండ్విచ్ లేదా సలాడ్‌లో ముక్కలు వేయండి.", "సాస్, సూప్ లేదా కూరలో ఉడికించండి."], careful: "టమాటా పుల్లగా ఉంటుంది; కొందరికి గుండెల్లో మంట పెరగవచ్చు. కొద్దిమందికి టమాటా అలర్జీ ఉంటుంది." },
  Zucchini: { name: "జుక్కిని", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి తోడ్పడుతుంది.", "పీచు ఆరోగ్యకరమైన జీర్ణక్రియకు సహాయపడుతుంది.", "పొటాషియం కండరాల పనితీరుకు, ద్రవాల సమతుల్యతకు తోడ్పడుతుంది."], season: "వేసవి నుంచి శరదృతువు ప్రారంభం వరకు.", tips: ["ముక్కలుగా కోసి కాల్చండి లేదా గ్రిల్ చేయండి.", "తురిమి పిండి వంటలు, బ్రెడ్ లేదా పాస్తా సాస్‌లో కలపండి."], careful: "అరుదుగా చేదుగా ఉండే గుమ్మడికాయల్లో సహజంగా ఉండే కుకుర్బిటాసిన్లు ఎక్కువగా ఉండవచ్చు; అసాధారణంగా చేదుగా ఉంటే తినకండి." },
  Blackberry: { name: "బ్లాక్‌బెర్రీ", benefits: ["పీచు జీర్ణక్రియ సరిగా ఉండటానికి తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి సహాయపడుతుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది."], season: "వేసవి నుంచి శరదృతువు ప్రారంభం వరకు; గడ్డకట్టిన బెర్రీలు ఏడాది పొడవునా లభిస్తాయి.", tips: ["కడిగిన బెర్రీలను తృణధాన్యాలు లేదా పెరుగులో కలపండి.", "గడ్డకట్టిన బ్లాక్‌బెర్రీలను స్మూతీలో వాడండి."], careful: "వార్ఫరిన్ వాడేవారు విటమిన్ కె తీసుకునే పరిమాణాన్ని స్థిరంగా ఉంచడం గురించి వైద్యులను అడగాలి." },
  Raspberry: { name: "రాస్ప్‌బెర్రీ", benefits: ["రాస్ప్‌బెర్రీలోని పీచు జీర్ణక్రియ క్రమంగా ఉండటానికి తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి సహాయపడుతుంది.", "మాంగనీస్ పోషకాల వినియోగానికి, ఎముకల సాధారణ నిర్వహణకు తోడ్పడుతుంది."], season: "వేసవి నుంచి శరదృతువు వరకు; గడ్డకట్టిన బెర్రీలు ఏడాది పొడవునా లభిస్తాయి.", tips: ["తాజా లేదా గడ్డకట్టిన రాస్ప్‌బెర్రీలను ఓట్స్ లేదా పెరుగుపై వేయండి.", "పాన్‌కేక్ మిశ్రమంలో కలపండి."], careful: "తాజా రాస్ప్‌బెర్రీలను తినే ముందు కడగండి. బెర్రీల అలర్జీ ఉంటే వీటిని తినకండి." },
  Cherry: { name: "చెర్రీ", benefits: ["పొటాషియం కండరాల పనితీరుకు, ద్రవాల సమతుల్యతకు తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి సహాయపడుతుంది.", "చెర్రీలో రంగు ఇచ్చే ఆంథోసయానిన్లు అనే మొక్కల పదార్థాలు ఉంటాయి."], season: "వసంతం చివరి నుంచి వేసవి వరకు.", tips: ["గింజ తీసిన తర్వాత తాజా చెర్రీలను తినండి.", "గింజలు తీసి ఓట్స్ లేదా పండ్ల సలాడ్‌లో కలపండి."], careful: "చిన్న పిల్లలకు ఇచ్చే ముందు గింజలు తీసేయండి. రాతిగింజ పండ్ల అలర్జీ ఉంటే చెర్రీలను తినకండి." },
  Grapes: { name: "ద్రాక్ష", benefits: ["ద్రాక్షలోని నీరు దీన్ని తేలికైన చిరుతిండిగా చేస్తుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది.", "ద్రాక్ష తొక్కలో పాలీఫెనాల్స్ అనే మొక్కల పదార్థాలు ఉంటాయి."], season: "వేసవి చివరి నుంచి శరదృతువు వరకు; ఏడాది పొడవునా లభిస్తుంది.", tips: ["కడిగి పూర్తిగా తినండి.", "చల్లని చిరుతిండిగా గడ్డకట్టండి; చిన్న పిల్లలకు పొడవుగా కోసి ఇవ్వండి."], careful: "మొత్తం ద్రాక్ష చిన్న పిల్లలకు గొంతులో అడ్డుపడే ప్రమాదం ఉంది; చిన్న ముక్కలుగా పొడవున కోయండి. వార్ఫరిన్ వాడేవారు విటమిన్ కె పరిమాణాన్ని స్థిరంగా ఉంచాలి." },
  Mango: { name: "మామిడి", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "బీటా కెరోటిన్ విటమిన్ ఏగా మారి చూపుకు సహాయపడుతుంది.", "పీచు జీర్ణక్రియకు తోడ్పడుతుంది."], season: "రకం, ప్రాంతాన్ని బట్టి వసంతం నుంచి వేసవి వరకు.", tips: ["తొక్క తీసి, గింజను తొలగించి ముక్కలుగా తినండి.", "ముక్కలను పెరుగు, సాల్సా లేదా స్మూతీలో కలపండి."], careful: "మామిడి తొక్కలోని పదార్థం పాయిజన్ ఐవీలో ఉండే పదార్థంలా కొందరికి ప్రతిచర్య కలిగించవచ్చు. మామిడితో పండ్ల అలర్జీ కూడా రావచ్చు." },
  Papaya: { name: "బొప్పాయి", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి సహాయపడుతుంది.", "బీటా కెరోటిన్ విటమిన్ ఏగా మారి చూపుకు తోడ్పడుతుంది.", "ఫోలేట్ కణాల సాధారణ పెరుగుదలకు అవసరం."], season: "ఉష్ణమండల ప్రాంతాల్లో ఏడాది పొడవునా లభిస్తుంది.", tips: ["గింజలు తీసి చల్లగా తినండి.", "ముక్కలను నిమ్మరసంతో పండ్ల సలాడ్‌లో కలపండి."], careful: "లేటెక్స్ అలర్జీ ఉన్నవారికి బొప్పాయితో ప్రతిచర్య రావచ్చు. గర్భిణులు వైద్యుల సూచన లేకుండా పచ్చి లేదా సగం పండిన బొప్పాయి తినకూడదు." },
  Pineapple: { name: "అనాస", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "మాంగనీస్ పోషకాల వినియోగానికి, ఎముకల సాధారణ నిర్వహణకు సహాయపడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి తోడ్పడుతుంది."], season: "ఏడాది పొడవునా లభిస్తుంది; పంట కాలం ప్రాంతాన్ని బట్టి మారుతుంది.", tips: ["గట్టి తొక్క, మధ్య భాగం తీసి తాజా ముక్కలుగా తినండి.", "వేపుడు వంటలో కలపండి లేదా గ్రిల్ చేయండి."], careful: "అనాస కొందరికి నోటిలో మంట కలిగించవచ్చు లేదా గుండెల్లో మంట పెంచవచ్చు. మందులు వాడేవారు ఆహార ప్రతిచర్యల గురించి ఫార్మసిస్ట్‌ను అడగండి." },
  Peach: { name: "పీచ్ పండు", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "కెరోటినాయిడ్లు విటమిన్ ఏగా మారి చూపుకు సహాయపడతాయి.", "పీచు జీర్ణక్రియకు తోడ్పడుతుంది."], season: "వసంతం చివరి నుంచి వేసవి వరకు.", tips: ["కడిగి తాజాగానే తినండి లేదా ఓట్స్‌లో ముక్కలు కలపండి.", "సులభమైన తీపి వంటకం కోసం పీచ్ ముక్కలను గ్రిల్ చేయండి."], careful: "రాతిగింజ పండ్లు లేదా పుప్పొడి అలర్జీ ఉన్నవారికి, ముఖ్యంగా పచ్చి పీచ్ తింటే ప్రతిచర్య రావచ్చు." },
  Plum: { name: "ప్లమ్", benefits: ["పీచు జీర్ణక్రియ సరిగా ఉండటానికి తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి సహాయపడుతుంది.", "పొటాషియం కండరాల పనితీరుకు, ద్రవాల సమతుల్యతకు తోడ్పడుతుంది."], season: "వేసవి నుంచి శరదృతువు ప్రారంభం వరకు.", tips: ["కడిగి, గింజ తీసి పూర్తిగా తినండి.", "సలాడ్‌లో ముక్కలు వేయండి లేదా ఓట్స్‌తో వడ్డించండి."], careful: "తినే ముందు గింజ తీసేయండి. రాతిగింజ పండ్ల అలర్జీ ఉంటే ప్లమ్ తినకండి." },
  Lemon: { name: "నిమ్మకాయ", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "వంటల్లో నిమ్మరసం వాడితే తక్కువ ఉప్పుతోనూ రుచి పెరుగుతుంది.", "గుజ్జు, తొక్కలో కొద్దిగా పీచు, మొక్కల పదార్థాలు ఉంటాయి."], season: "ఏడాది పొడవునా లభిస్తుంది.", tips: ["కూరగాయలు, బీన్స్ లేదా చేపలపై పిండండి.", "నీటిలో రసం కలపండి లేదా వంటలో తొక్క తురుము వాడండి."], careful: "నిమ్మరసం పుల్లగా ఉండటం వల్ల గుండెల్లో మంట పెరగవచ్చు లేదా పళ్లపై ప్రభావం చూపవచ్చు. పుల్లని పానీయం తర్వాత నీటితో నోరు పుక్కిలించండి." },
  Pomegranate: { name: "దానిమ్మ", benefits: ["దానిమ్మ గింజల్లో పీచు ఉంటుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి తోడ్పడుతుంది.", "ఎర్ర గింజల్లో పాలీఫెనాల్స్ అనే మొక్కల పదార్థాలు ఉంటాయి."], season: "శరదృతువు నుంచి శీతాకాలం వరకు.", tips: ["గింజలను సలాడ్ లేదా పెరుగులో కలపండి.", "పీచు కోసం రసం కంటే గింజలను తినండి."], careful: "దానిమ్మ రసం కొన్ని మందులతో ప్రతిచర్య కలిగించవచ్చు; దీనిపై ఆధారాలు మారుతుంటాయి. మందులు వాడుతూ తరచూ తాగాలనుకుంటే ఫార్మసిస్ట్‌ను అడగండి." },
  Beet: { name: "బీట్‌రూట్", benefits: ["ఫోలేట్ కణాల సాధారణ పెరుగుదల, పనితీరుకు తోడ్పడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి సహాయపడుతుంది.", "పొటాషియం కండరాల పనితీరుకు, ద్రవాల సమతుల్యతకు తోడ్పడుతుంది."], season: "వేసవి చివరి నుంచి శరదృతువు వరకు; నిల్వ చేసిన బీట్‌రూట్ ఏడాది పొడవునా లభిస్తుంది.", tips: ["మెత్తబడే వరకు కాల్చండి లేదా పచ్చిగా తురిమి సలాడ్‌లో వేయండి.", "ఆకుకూరలను ఇతర ఆకుకూరల్లా వండి తినండి."], careful: "బీట్‌రూట్ తింటే మూత్రం లేదా మలం గులాబీ/ఎరుపు రంగులో కనిపించవచ్చు; సాధారణంగా ఇది హానికరం కాదు. ఆక్సలేట్ మూత్రపిండ రాళ్లు ఉన్నవారు వ్యక్తిగత ఆహార సూచన తీసుకోండి." },
  Cabbage: { name: "క్యాబేజీ", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి సహాయపడుతుంది.", "పీచు జీర్ణక్రియకు తోడ్పడుతుంది."], season: "శరదృతువు నుంచి వసంతం వరకు; ఏడాది పొడవునా లభిస్తుంది.", tips: ["తురిమి స్లా లేదా సలాడ్‌లో కలపండి.", "సూప్, వేపుడు వంట లేదా టాకోలో చేర్చండి."], careful: "క్యాబేజీలో విటమిన్ కె ఉంటుంది; వార్ఫరిన్ వాడేవారు పరిమాణాన్ని స్థిరంగా ఉంచాలి. కొందరికి గ్యాస్ రావచ్చు." },
  Celery: { name: "సెలరీ", benefits: ["భోజనం లేదా చిరుతిండితో పాటు సెలరీ కొంత ద్రవాన్ని అందిస్తుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది.", "ఫోలేట్ కణాల సాధారణ పెరుగుదలకు సహాయపడుతుంది."], season: "ఏడాది పొడవునా లభిస్తుంది; చల్లని నెలల్లో తరచూ బాగా దొరుకుతుంది.", tips: ["కరకరలాడే ముక్కలను డిప్‌తో తినండి.", "సూప్, సలాడ్ లేదా కూరలో తరిగి కలపండి."], careful: "సెలరీ కొందరికి అలర్జీ కలిగించే ఆహారం. ఇందులో విటమిన్ కె ఉంటుంది; వార్ఫరిన్ వాడేవారు పరిమాణాన్ని స్థిరంగా ఉంచాలి." },
  Cucumber: { name: "దోసకాయ", benefits: ["దోసకాయలో నీరు ఎక్కువగా ఉంటుంది; భోజనంలో ద్రవాన్ని పెంచుతుంది.", "తొక్కతో తింటే కొంత పీచు లభిస్తుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది."], season: "వేసవి; ఏడాది పొడవునా లభిస్తుంది.", tips: ["కడిగి సలాడ్ లేదా సాండ్విచ్‌లో ముక్కలు వేయండి.", "రుచి కోసం మూలికలతో నీటిలో ముక్కలు కలపండి."], careful: "పుప్పొడి సంబంధిత ఆహార అలర్జీ ఉన్న కొందరికి పచ్చి దోసకాయతో ప్రతిచర్య రావచ్చు. వార్ఫరిన్ వాడేవారు విటమిన్ కె పరిమాణాన్ని స్థిరంగా ఉంచాలి." },
  Garlic: { name: "వెల్లుల్లి", benefits: ["విటమిన్ బి6 ఆహారం నుంచి శక్తిని ఉపయోగించుకోవడానికి సహాయపడుతుంది.", "మాంగనీస్ పోషకాల వినియోగానికి, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది.", "వెల్లుల్లి బలమైన రుచితో వంటకు రుచిని ఇస్తుంది; ఉప్పు తక్కువగా వాడేందుకు తోడ్పడవచ్చు."], season: "వేసవిలో పంట; నిల్వ చేసిన వెల్లుల్లి ఏడాది పొడవునా లభిస్తుంది.", tips: ["సాస్, సూప్ లేదా కాల్చిన కూరగాయల్లో తరిగి లేదా నూరి కలపండి.", "చేదు రాకుండా కొద్దిసేపే వండండి."], careful: "వెల్లుల్లి సప్లిమెంట్లు ఎక్కువగా తీసుకుంటే రక్తస్రావ ప్రమాదం లేదా మందులతో ప్రతిచర్య ఉండవచ్చు. సప్లిమెంట్లకు ముందు వైద్యుడు లేదా ఫార్మసిస్ట్‌ను అడగండి; సాధారణ ఆహార పరిమాణం వేరు." },
  Lettuce: { name: "లెట్యూస్", benefits: ["లెట్యూస్ ద్రవాన్ని అందించి భోజనానికి పరిమాణం, కరకరలాడే రుచిని జోడిస్తుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి తోడ్పడుతుంది.", "ఫోలేట్ కణాల సాధారణ పెరుగుదలకు సహాయపడుతుంది."], season: "చల్లని కాలం, తరచుగా వసంతం లేదా శరదృతువులో; ఏడాది పొడవునా లభిస్తుంది.", tips: ["ఆకులను బాగా కడిగి సలాడ్ లేదా రోల్‌లో వాడండి.", "వడ్డించే ముందు సాండ్విచ్‌లో తరిగిన లెట్యూస్ కలపండి."], careful: "ఆకుల లెట్యూస్‌లో విటమిన్ కె ఉంటుంది; వార్ఫరిన్ వాడేవారు పరిమాణాన్ని స్థిరంగా ఉంచాలి. తినే ముందు ఆకులను బాగా కడగండి." },
  Potato: { name: "బంగాళాదుంప", benefits: ["పొటాషియం కండరాల పనితీరుకు, ద్రవాల సమతుల్యతకు తోడ్పడుతుంది.", "విటమిన్ బి6 ఆహారం నుంచి శక్తిని ఉపయోగించుకోవడానికి సహాయపడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి తోడ్పడుతుంది; తొక్కలో పీచు ఉంటుంది."], season: "వేసవి చివరి, శరదృతువులో పంట; నిల్వ చేసినవి ఏడాది పొడవునా లభిస్తాయి.", tips: ["కాల్చండి, వేయించండి లేదా ఉడికించండి; పీచు కోసం తొక్క ఉంచండి.", "సమతుల్య భోజనం కోసం కూరగాయలు లేదా బీన్స్‌తో తినండి."], careful: "తీవ్రమైన మూత్రపిండ వ్యాధి ఉన్నవారు పొటాషియం గమనించాల్సి రావచ్చు. పచ్చగా మారిన లేదా ఎక్కువ మొలకలు వచ్చిన బంగాళాదుంపలను, చేదుగా ఉన్నవాటిని తినకండి." },
  Radish: { name: "ముల్లంగి", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి తోడ్పడుతుంది.", "పీచు జీర్ణక్రియకు సహాయపడుతుంది.", "ముల్లంగి ఎక్కువ తయారీ లేకుండానే వంటకు కరకరలాడే రుచి ఇస్తుంది."], season: "చాలా రకాల ముల్లంగికి వసంతం, శరదృతువు.", tips: ["కడిగి సలాడ్ లేదా సాండ్విచ్‌లో ముక్కలు వేయండి.", "కారం తగ్గేందుకు కాల్చి వడ్డించండి."], careful: "ఎక్కువ పరిమాణంలో తింటే కొందరికి గ్యాస్ లేదా జీర్ణ అసౌకర్యం రావచ్చు." },
  "Butternut Squash": { name: "బటర్నట్ గుమ్మడికాయ", benefits: ["బీటా కెరోటిన్ విటమిన్ ఏగా మారి చూపుకు తోడ్పడుతుంది.", "విటమిన్ సి రోగనిరోధక శక్తికి సహాయపడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి తోడ్పడుతుంది."], season: "శరదృతువు, శీతాకాలం; నిల్వ చేసిన గుమ్మడికాయ నెలల పాటు లభిస్తుంది.", tips: ["తొక్క తీసిన ముక్కలను మెత్తబడే వరకు కాల్చండి.", "ఉడికించిన గుమ్మడికాయను మెత్తగా చేసి సూప్‌లో కలపండి."], careful: "తీవ్రమైన మూత్రపిండ వ్యాధి ఉన్నవారు పొటాషియం గురించి వ్యక్తిగత సూచన తీసుకోండి. గట్టి పచ్చి గుమ్మడికాయను కోసేటప్పుడు జాగ్రత్తగా ఉండండి." },
  Asparagus: { name: "ఆస్పరాగస్", benefits: ["ఫోలేట్ కణాల సాధారణ పెరుగుదల, పనితీరుకు తోడ్పడుతుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి సహాయపడుతుంది.", "పీచు జీర్ణక్రియకు తోడ్పడుతుంది."], season: "వసంతం.", tips: ["గట్టి చివరలు తీసి కాల్చండి, ఆవిరి మీద ఉడికించండి లేదా గ్రిల్ చేయండి.", "ఉడికించిన కాడలను గుడ్లు లేదా ధాన్యాల భోజనంలో కలపండి."], careful: "ఆస్పరాగస్‌లో విటమిన్ కె ఉంటుంది; వార్ఫరిన్ వాడేవారు పరిమాణాన్ని స్థిరంగా ఉంచాలి. మూత్రపిండ వ్యాధి ఉన్నవారు తమ వైద్య బృందం సూచనలు పాటించాలి." },
  "Brussels Sprouts": { name: "బ్రస్సెల్స్ మొలకలు", benefits: ["విటమిన్ సి రోగనిరోధక శక్తికి, కొల్లాజెన్ తయారీకి తోడ్పడుతుంది.", "విటమిన్ కె రక్తం గడ్డకట్టే సాధారణ ప్రక్రియకు, ఎముకల ఆరోగ్యానికి సహాయపడుతుంది.", "పీచు జీర్ణక్రియ సరిగా ఉండటానికి తోడ్పడుతుంది."], season: "శరదృతువు నుంచి వసంతం ప్రారంభం వరకు.", tips: ["చివరలు తీసి సగానికి కోసి, గోధుమ రంగు వచ్చే వరకు కాల్చండి.", "కరకరలాడే సలాడ్ కోసం పచ్చి మొలకలను సన్నగా తురమండి."], careful: "బ్రస్సెల్స్ మొలకల్లో విటమిన్ కె ఉంటుంది; వార్ఫరిన్ వాడేవారు పరిమాణాన్ని స్థిరంగా ఉంచాలి. కొందరికి గ్యాస్ రావచ్చు." }
};

// Translate shared nutrient and benefit-filter names once, then reuse them in every card.
const teluguNutrients = {
  "Fiber": "పీచు", "Vitamin C": "విటమిన్ సి", "Polyphenols": "పాలీఫెనాల్స్",
  "Vitamin A": "విటమిన్ ఏ", "Potassium": "పొటాషియం", "Monounsaturated fat": "మోనోఅన్‌శాచురేటెడ్ కొవ్వు",
  "Folate": "ఫోలేట్", "Vitamin B6": "విటమిన్ బి6", "Anthocyanins": "ఆంథోసయానిన్లు",
  "Water": "నీరు", "Vitamin K": "విటమిన్ కె", "Copper": "రాగి",
  "Manganese": "మాంగనీస్", "Lycopene": "లైకోపీన్", "Vitamin E": "విటమిన్ ఈ",
  "Vitamin A (some varieties)": "విటమిన్ ఏ (కొన్ని రకాల్లో)", "Vitamin A (from beta-carotene)": "విటమిన్ ఏ (బీటా కెరోటిన్ నుంచి)",
  "Vitamin A (from carotenoids)": "విటమిన్ ఏ (కెరోటినాయిడ్ల నుంచి)", "Vitamin K1": "విటమిన్ కె1",
  "Beta-carotene": "బీటా కెరోటిన్", "Lutein": "ల్యూటీన్", "B vitamins": "బి విటమిన్లు",
  "Selenium": "సెలీనియం", "Riboflavin": "రిబోఫ్లేవిన్", "Niacin": "నియాసిన్",
  "Iron": "ఇనుము", "Magnesium": "మెగ్నీషియం", "Calcium": "కాల్షియం",
  "Vitamin A (leafy varieties)": "విటమిన్ ఏ (ఆకుకూర రకాల్లో)", "Citrate": "సిట్రేట్",
  "Vitamin B6 (small amount)": "విటమిన్ బి6 (కొద్దిగా)", "Vitamin C (small amount)": "విటమిన్ సి (కొద్దిగా)",
  "Potassium (small amount)": "పొటాషియం (కొద్దిగా)", "Quercetin": "క్వెర్సెటిన్"
};
const teluguTags = { Heart: "గుండె ఆరోగ్యం", Digestion: "జీర్ణక్రియ", Immunity: "రోగనిరోధక శక్తి", Eyes: "చూపు", Skin: "చర్మం", Bones: "ఎముకలు" };

// Give the page a consistent bilingual object for every produce item.
const produceData = englishProduceData.map((item) => {
  const telugu = produceTranslations[item.name];
  const translateNutrient = (nutrient) => teluguNutrients[nutrient] || nutrient;
  return {
    name: { en: item.name, te: telugu.name },
    emoji: item.emoji,
    // For example, "Bell Pepper" loads models/bell-pepper.glb.
    model: `models/${item.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}.glb`,
    category: { en: item.category, te: item.category === "fruit" ? "పండు" : "కూరగాయ" },
    nutrients: { en: item.nutrients, te: item.nutrients.map(translateNutrient) },
    benefits: { en: item.benefits, te: telugu.benefits },
    vitaminsMinerals: { en: item.vitaminsMinerals, te: item.vitaminsMinerals.map(translateNutrient) },
    season: { en: item.season, te: telugu.season },
    tips: { en: item.tips, te: telugu.tips },
    careful: { en: item.careful, te: telugu.careful },
    tags: { en: item.tags, te: item.tags.map((tag) => teluguTags[tag]) }
  };
});
